// Learned word tables: per-class weights for words and word pairs (generated by tools/analyzers/emo_table.py),
// scored like a lexicon: sum the weights of the words present, add the bias, softmax. Tokenization matches the
// trainer (lowercase words incl. inner apostrophes, plus ! and ?; unigrams and bigrams, each counted once).
const TOKEN = /__\w+|[a-z]+(?:'[a-z]+)?|[!?:]/g;

export function loadTable(t) {
  if (t.index) return t;
  const bin = typeof atob === "function" ? atob(t.w) : Buffer.from(t.w, "base64").toString("binary");
  const w = new Int8Array(bin.length);
  for (let k = 0; k < bin.length; k++) w[k] = (bin.charCodeAt(k) << 24) >> 24;
  t.weights = w;
  t.index = new Map(t.vocab.map((v, k) => [v, k]));
  return t;
}

export function tokenize(text) {
  return text.toLowerCase().match(TOKEN) || [];
}

export function scoreTable(t, text) {
  return scoreTokens(t, tokenize(text));
}

// Score an already tokenized text (callers cache per-unit tokens and concatenate them for beats / scenes).
export function scoreTokens(t, toks) {
  loadTable(t);
  const n = t.classes.length, z = t.bias.slice(), idx = t.index, w = t.weights, sc = t.scale;
  const seen = new Set();
  const add = (g) => {
    if (seen.has(g)) return;
    seen.add(g);
    const k = idx.get(g);
    if (k === undefined) return;
    const o = k * n;
    for (let c = 0; c < n; c++) z[c] += sc * w[o + c];
  };
  for (let k = 0; k < toks.length; k++) { add(toks[k]); if (k + 1 < toks.length) add(toks[k] + " " + toks[k + 1]); }
  let mx = -Infinity;
  for (const v of z) mx = Math.max(mx, v);
  let s = 0;
  for (let c = 0; c < n; c++) { z[c] = Math.exp(z[c] - mx); s += z[c]; }
  for (let c = 0; c < n; c++) z[c] /= s;
  return z;
}
